export const createPendingHumanDesignChart = (note: string): HumanDesignChart => {
  const now = new Date().toISOString();

  return {
    type: null,
    strategy: null,
    authority: null,
    profile: null,
    definition: null,
    incarnationCross: {
      name: null,
      gates: [],
    },
    centers: emptyHumanDesignCenters(),
    gates: [],
    channels: [],
    diagnostic: null,
    personalityActivations: [],
    designActivations: [],
    raw_personality_gates: [],
    raw_design_gates: [],
    variables: null,
    digestion: null,
    cognition: null,
    motivation: null,
    environment: null,
    perspective: null,
    status: "pending",
    source: "pending",
    note,
    generatedAt: now,
    updatedAt: now,
    calculationStatus: "pending",
    hdEngineVersion: "gaia-hd-v1",
    hdAuditStatus: "pending",
  };
};

export const createErrorHumanDesignChart = (note: string): HumanDesignChart => {
  const now = new Date().toISOString();

  return {
    ...createPendingHumanDesignChart(note),
    status: "error",
    source: "error",
    generatedAt: now,
    updatedAt: now,
    calculationStatus: "error",
  };
};

